$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.IO.Compression.FileSystem
$root = Split-Path $PSScriptRoot -Parent
$backup = Join-Path $root ('Review Backups/diagram-descriptions-' + (Get-Date -Format 'yyyyMMdd-HHmmss'))
New-Item -ItemType Directory -Force -Path $backup | Out-Null

# Update the standalone chapter and create a new combined deliverable from the
# latest TOC-refreshed copy, avoiding any document currently locked in Word.
$jobs = @(
  @{ Source='Chapter 3.docx'; Destination='Chapter 3.docx'; Label='Chapter 3' },
  @{ Source='Chapters 1-3 with Updated Table of Contents.docx'; Destination='Chapters 1-3 with Updated Diagram Descriptions.docx'; Label='Combined Chapters 1-3' }
)

$replacements = [ordered]@{
  'Agile is an iterative system-development approach' = 'Figure 1 should be read as a recurring development cycle, not as a one-time sequence. Planning identifies the workflow or requirement to address; design translates that requirement into pages, forms, data relationships, and access rules; development builds a selected increment; and testing and review determine whether that increment satisfies the stated requirement. Findings and feedback return to planning, so a later increment may refine an earlier design. The Launch stage means release only after the relevant increment has been verified. The figure organizes the project''s membership, renewal, attendance, inventory, sales, and reporting work, but it does not claim use of a particular Agile framework, a fixed iteration length, completed evaluation results, or a production deployment.'
  'The Administrator entity submits credentials, application and renewal review decisions' = 'The Administrator entity exchanges credentials, application and renewal review decisions, membership operations, product and stock updates, product-sale entries, staff-account controls, phone-pairing controls, and report or activity-log queries. These are separate authorized requests rather than one combined transaction. Phone-pairing controls concern the attendance camera connection only. Website trusted-browser and authenticator verification are a separate website-login security workflow; they neither authorize nor replace the attendance scanner''s independent operator session. Queries retrieve information; they do not themselves change the underlying business records.'
  'The system returns administrator access results, operation confirmations, member and staff information, device states, reports, and recorded activity.' = 'The system returns administrator access results, operation confirmations, member and staff information, phone-pairing states, reports, and recorded activity. The return flow lets the administrator confirm a submitted operation or inspect information within the permitted scope. Viewing an existing member personal profile remains read-only. Membership approval, renewal, and plan changes are operational responsibilities and do not authorize editing that member''s personal profile. The scanner''s password-based operator session is deliberately separate from the administrator''s website trusted-browser session, so a scanner sign-in does not silently transfer or revoke website access.'
  'Figure 3 reproduces the complete user-supplied Level 1 DFD in Gane-Sarson notation.' = 'Figure 3 is the supplied Level 1 Data Flow Diagram. Read a labeled arrow from its source to its destination: an arrow from an actor to a process is an input or request, an arrow from a process to a store records or retrieves data, and an arrow back to an actor is a result. Rectangles identify external actors, rounded boxes identify numbered processes, and open-ended symbols identify named data stores. Repeated store symbols refer to the same logical record set, not duplicate tables. D12 is a retained mobile scan-event table label in the diagram; current scanner attendance is recorded through the attendance workflow and supporting private scanner-session records, so D12 must not be read as proof of an active scanner screen or a separate user permission. The diagram is a logical information-flow view; it does not show page navigation, API calls, every private table, or every access-control check.'
  'Processes 8.0 and 9.0 have distinct outputs.' = 'Processes 8.0 and 9.0 must be read separately. Generate Reports reads the relevant operational records to produce the selected preview, print layout, or supported export. Activity Logs reads previously recorded events and returns the administrator''s filtered results. The Activity Logs viewer does not create staff accounts, change pairing settings, or modify logged events; those actions occur in their respective operational processes and may then be recorded in the log. This distinction prevents a reporting or monitoring arrow from being mistaken for permission to perform the underlying operation.'
  '5.0 Record and View Attendance.' = '5.0 Record and View Attendance. An authorized administrator or staff operator scans a member QR code with a supported computer or phone camera. The operator signs in to the attendance scanner using the same authorized account credentials, but the scanner maintains its own password-based attendance session; it does not require or use the website administrator authenticator or trusted-browser proof. When another scanner requests the same operator session, the currently active scanner is asked to approve or deny that handoff. The database validates the operator and member, checks for an open visit, and records check-in or check-out in attendance. recorded_by and checked_out_by identify the operators for each event. Private attendance scan requests and scanner-session records support duplicate protection and the scanner handoff. Paired phones use administrator-managed pairing sessions and policy; pairing connects the phone camera to the attendance workflow but does not replace operator authentication.'
  'Figure 4 summarizes actor participation in the nine main functional areas of IronGrind:' = 'Figure 4 is read as a role-and-goal summary. The rectangle marks the system boundary, the ovals mark broad functional capabilities, and the external actor icons identify Member / Applicant, Authorized Staff, and Administrator. A solid association means that the role participates in that functional area; it does not show data movement, screen order, or permission to perform every sub-action inside the oval. The detailed paragraphs and implementation controls define the narrower permissions. For example, User Management is associated with more than one role, yet members update only their own permitted information, administrators view member personal profiles without editing them, and staff do not receive general profile access.'
  'User Login verifies an account and establishes access for its role and active-account state.' = 'User Login verifies an account and establishes access for its role and active-account state. For website administrators, this function covers trusted-browser proof, initial TOTP registration, replacement-browser approval, fresh TOTP before transfer, and explicit trust revocation. Both approving and requesting website sessions represent the same Administrator actor; they do not create new organizational roles. The attendance scanner is intentionally different: it accepts the same authorized administrator or staff credentials into a separate, password-based scanner session, without website TOTP or trusted-browser verification. Scanner handoff approval is requested from the first active scanner only, and does not log out or alter the user''s website dashboard session. Figure 4 retains nine broad function ovals because these are authentication scenarios within the existing role workflows, not separate business actors.'
  'Figure 5 presents the public-schema relationship overview for IronGrind.' = 'Figure 5 presents the public-schema relationship overview for IronGrind. It is read as a structural model: each entity box represents a table, PK marks the record identifier, FK marks a field that references another table, UQ marks an individually unique value, and each connector represents a declared relationship. Selected keys and descriptive attributes are shown to keep the overview readable; the data dictionary provides the complete documented field definitions. The auth.users card is a Supabase-managed identity reference and is not counted as an application-owned public table.'
  'This figure intentionally covers the public schema rather than the entire application-owned database.' = 'This figure intentionally covers the public schema rather than the entire application-owned database. The checked-in migration model currently documents twenty-three application tables, 235 fields, and thirty-eight declared foreign keys: twelve public tables and eleven private supporting tables. The private structures support scanner sessions and handoff approvals, attendance requests, login attempts, scoped account sessions, and administrator/member device authorization. Their definitions belong in the data dictionary and separate security reference material. The overview describes stored relationships, not role permissions or proof of production deployment; it is based on the checked-in migrations and supplied schema material, not a new live-database inspection.'
  'Figure 63 presents the original ten-week development schedule for IronGrind' = 'Figure 63 is read from left to right as the original planned ten-week schedule for IronGrind, from August 24 to October 28, 2026. Each row names a planned activity, the date column states its planned range, and the colored bar locates it in its assigned week. Planning occupies Weeks 1-4 and includes client identification, the initial interview, project conceptualization, and proposal drafting. Design occupies Weeks 5-8 and includes interface design, prototype development, client feedback, and refinement. Development occupies Weeks 9-10 and includes frontend, backend, database, API, supporting work, and chapter preparation. The figure documents intended sequencing only; it does not independently establish actual completion dates, effort, evaluation outcomes, or production readiness.'
}

function TextOf($node, $ns) { return (($node.SelectNodes('.//w:t', $ns) | ForEach-Object InnerText) -join '') }
function PutText($node, $value, $ns) {
  $texts = @($node.SelectNodes('.//w:t', $ns)); if ($texts.Count -eq 0) { throw 'Target has no text run.' }
  $texts[0].InnerText = $value; foreach ($text in $texts | Select-Object -Skip 1) { $text.InnerText = '' }
}

$report = [Collections.Generic.List[string]]::new()
foreach ($job in $jobs) {
  $source = Join-Path $root $job.Source; $destination = Join-Path $root $job.Destination
  if (-not (Test-Path -LiteralPath $source)) { throw "Missing source: $source" }
  Copy-Item -LiteralPath $source -Destination (Join-Path $backup $job.Source) -Force
  $stage = Join-Path $backup ($job.Label + ' staged.docx'); Copy-Item -LiteralPath $source -Destination $stage -Force
  $zip = [IO.Compression.ZipFile]::Open($stage, 'Update')
  try {
    $entry = $zip.GetEntry('word/document.xml'); $reader = [IO.StreamReader]::new($entry.Open())
    try { [xml]$doc = $reader.ReadToEnd() } finally { $reader.Dispose() }
    $ns = [Xml.XmlNamespaceManager]::new($doc.NameTable); $ns.AddNamespace('w', 'http://schemas.openxmlformats.org/wordprocessingml/2006/main')
    $paragraphs = @($doc.SelectNodes('//w:body//w:p', $ns)); $changed = 0
    foreach ($prefix in $replacements.Keys) {
      $matches = @($paragraphs | Where-Object { (TextOf $_ $ns).Trim().StartsWith($prefix) })
      if ($matches.Count -ne 1) { throw "$($job.Label): expected one '$prefix' paragraph; found $($matches.Count)." }
      PutText $matches[0] $replacements[$prefix] $ns; $changed++
    }
    $entry.Delete(); $writer = [IO.StreamWriter]::new($zip.CreateEntry('word/document.xml').Open(), [Text.UTF8Encoding]::new($false))
    try { $doc.Save($writer) } finally { $writer.Dispose() }
  } finally { $zip.Dispose() }
  Copy-Item -LiteralPath $stage -Destination $destination -Force
  $report.Add("PASS: $($job.Label) - $changed diagram-description paragraphs updated.")
}
$report.Add('PASS: Prose explains how to read each diagram, distinguishes logical diagrams from authorization enforcement, and separates website administrator authentication from password-based attendance-scanner sessions.')
$report.Add("Backup: $backup")
$report | Set-Content -LiteralPath (Join-Path $root 'Review Evidence/Diagram Description Revision Verification.txt') -Encoding utf8
$report
